import { expect } from "chai";
import { ethers } from "ethers";
import nacl from "tweetnacl";
import {
  init,
  poseidonHash,
  deriveKeysFromWallet,
  encryptOutput,
  decryptOutput,
  encodeOutputBlob,
  decodeOutputBlob,
} from "../src/crypto";
import { MerkleTree } from "../src/merkle";
import { buildEntry, computeNullifier, ETH_TOKEN_ADDRESS } from "../src/entry";
import { findMyOutputs, Output } from "../src/events";

before(async () => {
  await init();
});

describe("crypto", () => {
  it("poseidonHash is deterministic", () => {
    expect(poseidonHash([1n, 2n])).to.equal(poseidonHash([1n, 2n]));
  });

  it("poseidonHash changes with different inputs", () => {
    expect(poseidonHash([1n, 2n])).to.not.equal(poseidonHash([1n, 3n]));
  });

  it("poseidonHash returns a bigint", () => {
    const h = poseidonHash([42n]);
    expect(typeof h).to.equal("bigint");
    expect(h > 0n).to.be.true;
  });

  it("deriveKeysFromWallet returns all expected fields", async () => {
    const wallet = ethers.Wallet.createRandom();
    const keys = await deriveKeysFromWallet(wallet);
    expect(keys.spendingPrivKey).to.be.a("bigint");
    expect(keys.spendingPubkey).to.equal(poseidonHash([keys.spendingPrivKey]));
    expect(keys.nullifierKey).to.equal(poseidonHash([keys.viewingPrivKey]));
    expect(keys.encryption.privateKey).to.be.instanceOf(Uint8Array);
    expect(keys.encryption.publicKey).to.be.instanceOf(Uint8Array);
    expect(keys.encryption.privateKey).to.have.lengthOf(32);
    expect(keys.encryption.publicKey).to.have.lengthOf(32);
  });

  it("deriveKeysFromWallet is deterministic", async () => {
    const wallet = ethers.Wallet.createRandom();
    const a = await deriveKeysFromWallet(wallet);
    const b = await deriveKeysFromWallet(wallet);
    expect(a.spendingPrivKey).to.equal(b.spendingPrivKey);
    expect(a.viewingPrivKey).to.equal(b.viewingPrivKey);
    expect(Buffer.from(a.encryption.privateKey).toString("hex"))
      .to.equal(Buffer.from(b.encryption.privateKey).toString("hex"));
  });

  it("deriveKeysFromWallet differs per wallet", async () => {
    const a = await deriveKeysFromWallet(ethers.Wallet.createRandom());
    const b = await deriveKeysFromWallet(ethers.Wallet.createRandom());
    expect(a.spendingPrivKey).to.not.equal(b.spendingPrivKey);
  });
});

describe("NaCl box encryption", () => {
  it("encrypt then decrypt recovers blinding and amount", () => {
    const recipient = nacl.box.keyPair();
    const blinding = 123456789n;
    const amount   = ethers.parseEther("1");

    const { encrypted, viewTag } = encryptOutput(blinding, amount, recipient.publicKey);
    const decrypted = decryptOutput(encrypted, recipient.secretKey);

    expect(decrypted).to.not.be.null;
    expect(decrypted!.blinding).to.equal(blinding);
    expect(decrypted!.amount).to.equal(amount);
    expect(decrypted!.viewTag).to.equal(viewTag);
  });

  it("wrong key fails MAC and returns null", () => {
    const recipient = nacl.box.keyPair();
    const eve       = nacl.box.keyPair();
    const { encrypted } = encryptOutput(111n, 222n, recipient.publicKey);
    const decrypted = decryptOutput(encrypted, eve.secretKey);
    expect(decrypted).to.be.null;
  });

  it("encode/decode blob roundtrips", () => {
    const recipient = nacl.box.keyPair();
    const { encrypted, viewTag } = encryptOutput(42n, 99n, recipient.publicKey);
    const blob    = encodeOutputBlob(encrypted, viewTag);
    const decoded = decodeOutputBlob(blob);
    expect(decoded).to.not.be.null;
    expect(decoded!.viewTag).to.equal(viewTag);
    expect(Buffer.from(decoded!.encrypted.ephemeralPub).toString("hex"))
      .to.equal(Buffer.from(encrypted.ephemeralPub).toString("hex"));
  });

  it("decodeOutputBlob returns null for empty blob", () => {
    expect(decodeOutputBlob("0x")).to.be.null;
  });

  it("blob is 138 bytes with version prefix", () => {
    const { encrypted, viewTag } = encryptOutput(1n, 2n, nacl.box.keyPair().publicKey);
    const blob = encodeOutputBlob(encrypted, viewTag);
    const buf = ethers.getBytes(blob);
    expect(buf).to.have.lengthOf(138);
    expect(buf[0]).to.equal(0x01);
  });
});

describe("MerkleTree", () => {
  it("empty tree has a deterministic root", () => {
    expect(new MerkleTree().getRoot()).to.equal(new MerkleTree().getRoot());
  });

  it("root changes after insert", () => {
    const tree = new MerkleTree();
    const empty = tree.getRoot();
    tree.insert(42n);
    expect(tree.getRoot()).to.not.equal(empty);
  });

  it("proof has 32 elements (LEVELS=32 matches circuit)", () => {
    const tree = new MerkleTree();
    tree.insert(100n);
    const proof = tree.getProof(0);
    expect(proof.pathElements).to.have.lengthOf(32);
    expect(proof.pathIndices).to.have.lengthOf(32);
  });

  it("proof hashes back to root", () => {
    const tree = new MerkleTree();
    tree.insert(11n);
    tree.insert(22n);
    tree.insert(33n);
    const root = tree.getRoot();
    const { pathElements, pathIndices } = tree.getProof(1);
    let cur = 22n;
    for (let i = 0; i < 32; i++) {
      const [l, r] = pathIndices[i] === 0 ? [cur, pathElements[i]] : [pathElements[i], cur];
      cur = poseidonHash([l, r]);
    }
    expect(cur).to.equal(root);
  });
});

describe("entry", () => {
  it("buildEntry produces correct commitment", () => {
    const pubkey = poseidonHash([12345n]);
    const nullifierKey = poseidonHash([99999n]);
    const blinding = 999n;
    const amount   = ethers.parseEther("1");
    const entry = buildEntry(pubkey, nullifierKey, blinding, amount, ETH_TOKEN_ADDRESS);
    expect(entry.commitment).to.equal(poseidonHash([pubkey, nullifierKey, blinding, amount, ETH_TOKEN_ADDRESS]));
  });

  it("computeNullifier depends on leafIndex", () => {
    const nullifierKey = poseidonHash([42n]);
    const n0 = computeNullifier(nullifierKey, 0);
    const n1 = computeNullifier(nullifierKey, 1);
    expect(n0).to.not.equal(n1);
    expect(n0).to.equal(poseidonHash([nullifierKey, 0n]));
  });

  it("different pubkey gives different commitment", () => {
    const nk = poseidonHash([0n]);
    const a = buildEntry(poseidonHash([1n]), nk, 0n, 1n, 0n);
    const b = buildEntry(poseidonHash([2n]), nk, 0n, 1n, 0n);
    expect(a.commitment).to.not.equal(b.commitment);
  });
});

describe("findMyOutputs", () => {
  it("identifies encrypted outputs belonging to me", () => {
    const myKey    = nacl.box.keyPair();
    const myPubkey = poseidonHash([11111n]);
    const myVK     = poseidonHash([22222n]);  // nullifierKey
    const amount   = ethers.parseEther("1");
    const blinding = 777n;

    const myEntry = buildEntry(myPubkey, myVK, blinding, amount, ETH_TOKEN_ADDRESS);
    const { encrypted, viewTag } = encryptOutput(blinding, amount, myKey.publicKey);
    const blob = encodeOutputBlob(encrypted, viewTag);

    const otherKey  = nacl.box.keyPair();
    const { encrypted: oe, viewTag: ot } = encryptOutput(1n, 2n, otherKey.publicKey);
    const otherBlob = encodeOutputBlob(oe, ot);

    const outputs: Output[] = [
      { commitment: myEntry.commitment, leafIndex: 0, encryptedBlob: blob, spentNullifiers: [0n, 0n], blockNumber: 1, transactionIndex: 0, logIndex: 0, tokenAddress: 0n },
      { commitment: 12345n, leafIndex: 1, encryptedBlob: otherBlob, spentNullifiers: [0n, 0n], blockNumber: 1, transactionIndex: 0, logIndex: 1, tokenAddress: 0n },
    ];

    const found = findMyOutputs(outputs, myPubkey, myVK, myKey.secretKey);
    expect(found).to.have.lengthOf(1);
    expect(found[0].commitment).to.equal(myEntry.commitment);
    expect(found[0].leafIndex).to.equal(0);
  });

  it("returns empty for no matches", () => {
    const myKey    = nacl.box.keyPair();
    const myPubkey = poseidonHash([55555n]);
    const myVK     = poseidonHash([66666n]);  // nullifierKey
    const otherKey = nacl.box.keyPair();
    const { encrypted, viewTag } = encryptOutput(1n, 2n, otherKey.publicKey);

    const outputs: Output[] = [
      { commitment: 99999n, leafIndex: 0, encryptedBlob: encodeOutputBlob(encrypted, viewTag), spentNullifiers: [0n, 0n], blockNumber: 1, transactionIndex: 0, logIndex: 0, tokenAddress: 0n },
    ];

    expect(findMyOutputs(outputs, myPubkey, myVK, myKey.secretKey)).to.have.lengthOf(0);
  });
});

import { ethers } from "ethers";
import nacl from "tweetnacl";

const { buildPoseidon } = require("circomlibjs");

let poseidon: any;
let F: any;

export interface NaclKeypair {
  privateKey: Uint8Array;  // 32 bytes X25519
  publicKey: Uint8Array;   // 32 bytes X25519
}

export interface HaliasKeys {
  spendingPrivKey: bigint;  // private circuit witness
  spendingPubkey: bigint;   // Poseidon(spendingPrivKey) — registered on-chain
  viewingPrivKey: bigint;   // private circuit witness
  nullifierKey: bigint;     // Poseidon(viewingPrivKey) — nk: baked into commitments + nullifiers
  encryption: NaclKeypair;  // X25519 keypair for NaCl box output encryption
}

export interface Signer {
  signMessage(message: string): Promise<string>;
}

const DERIVATION_MESSAGE =
  "halias key derivation v1\n\nSign this message to derive your halias keys.\nThis does NOT authorize any transaction.";

export async function init(): Promise<void> {
  const p = await buildPoseidon();
  poseidon = p;
  F = poseidon.F;
}

export function poseidonHash(inputs: bigint[]): bigint {
  if (!poseidon) throw new Error("Call init() first");
  return F.toObject(poseidon(inputs));
}

export async function deriveKeysFromWallet(signer: Signer): Promise<HaliasKeys> {
  const signature = await signer.signMessage(DERIVATION_MESSAGE);
  const seedBytes = ethers.getBytes(ethers.keccak256(ethers.getBytes(signature)));
  const seed = BigInt(ethers.hexlify(seedBytes));

  const spendingPrivKey = poseidonHash([seed, 0n]);
  const viewingPrivKey  = poseidonHash([seed, 1n]);

  // X25519 encryption key: domain byte 0x02
  const encPriv = ethers.getBytes(
    ethers.keccak256(ethers.concat([seedBytes, new Uint8Array([2])]))
  );
  const encKeypair = nacl.box.keyPair.fromSecretKey(encPriv);

  return {
    spendingPrivKey,
    spendingPubkey: poseidonHash([spendingPrivKey]),
    viewingPrivKey,
    nullifierKey:   poseidonHash([viewingPrivKey]),
    encryption:     { privateKey: encPriv, publicKey: encKeypair.publicKey },
  };
}

// ── NaCl box output encryption ────────────────────────────────
//
// Blob layout (138 bytes total):
//   version    [0]        1 byte   — 0x01 (NaCl box); 0x00 reserved as invalid
//   viewTag    [1]        1 byte   — first byte of shared key, fast pre-reject
//   ephPub     [2..33]   32 bytes  — X25519 ephemeral public key
//   nonce      [34..57]  24 bytes  — XSalsa20 nonce
//   ciphertext [58..137] 80 bytes  — XSalsa20-Poly1305 of (blinding || amount)

const BLOB_VERSION = 0x01;

export interface EncryptedOutput {
  ephemeralPub: Uint8Array;  // 32 bytes
  nonce: Uint8Array;         // 24 bytes
  ciphertext: Uint8Array;    // 80 bytes (64 plaintext + 16 MAC)
}

export function encryptOutput(
  blinding: bigint,
  amount: bigint,
  recipientPub: Uint8Array,
): { encrypted: EncryptedOutput; viewTag: number } {
  const ephemeral = nacl.box.keyPair();
  const sharedKey = nacl.box.before(recipientPub, ephemeral.secretKey);
  const viewTag = sharedKey[0];
  const nonce = nacl.randomBytes(nacl.box.nonceLength);

  const message = new Uint8Array(64);
  message.set(ethers.getBytes(ethers.toBeHex(blinding, 32)), 0);
  message.set(ethers.getBytes(ethers.toBeHex(amount, 32)), 32);

  const ciphertext = nacl.box.after(message, nonce, sharedKey);
  return {
    encrypted: { ephemeralPub: ephemeral.publicKey, nonce, ciphertext },
    viewTag,
  };
}

export function decryptOutput(
  encrypted: EncryptedOutput,
  encPrivKey: Uint8Array,
): { blinding: bigint; amount: bigint; viewTag: number } | null {
  try {
    const sharedKey = nacl.box.before(encrypted.ephemeralPub, encPrivKey);
    const viewTag = sharedKey[0];
    const message = nacl.box.open.after(encrypted.ciphertext, encrypted.nonce, sharedKey);
    if (!message) return null;
    return {
      blinding: BigInt(ethers.hexlify(message.slice(0, 32))),
      amount:   BigInt(ethers.hexlify(message.slice(32, 64))),
      viewTag,
    };
  } catch {
    return null;
  }
}

export function encodeOutputBlob(encrypted: EncryptedOutput, viewTag: number): string {
  const buf = new Uint8Array(138);
  buf[0] = BLOB_VERSION;
  buf[1] = viewTag;
  buf.set(encrypted.ephemeralPub, 2);
  buf.set(encrypted.nonce, 34);
  buf.set(encrypted.ciphertext, 58);
  return ethers.hexlify(buf);
}

export function decodeOutputBlob(blob: string): { viewTag: number; encrypted: EncryptedOutput } | null {
  if (blob === "0x" || blob.length < 10) return null;
  try {
    const buf = ethers.getBytes(blob);
    if (buf.length < 138 || buf[0] !== BLOB_VERSION) return null;
    return {
      viewTag: buf[1],
      encrypted: {
        ephemeralPub: buf.slice(2, 34),
        nonce:        buf.slice(34, 58),
        ciphertext:   buf.slice(58, 138),
      },
    };
  } catch {
    return null;
  }
}

import { poseidonHash } from "./crypto";

const LEVELS = 32; // must match POOL_LEVELS baked into the circuit WASM

export class MerkleTree {
  levels: number;
  leaves: bigint[];
  private _zeros: bigint[] | null = null;
  private _cachedLayers: bigint[][] | null = null;

  constructor(levels: number = LEVELS) {
    this.levels = levels;
    this.leaves = [];
  }

  get zeros(): bigint[] {
    if (!this._zeros) this._zeros = this._computeZeros();
    return this._zeros;
  }

  _computeZeros(): bigint[] {
    const zeros: bigint[] = [0n];
    for (let i = 0; i < this.levels; i++) {
      zeros.push(poseidonHash([zeros[i], zeros[i]]));
    }
    return zeros;
  }

  insert(leaf: bigint) {
    this.leaves.push(leaf);
    this._cachedLayers = null;
  }

  _buildLayers(): bigint[][] {
    if (this._cachedLayers) return this._cachedLayers;
    const layers: bigint[][] = [[...this.leaves]];
    for (let level = 0; level < this.levels; level++) {
      const cur = layers[level];
      const next: bigint[] = [];
      const len = Math.max(cur.length, 1);
      for (let i = 0; i < Math.ceil(len / 2); i++) {
        const left  = cur[2 * i]     ?? this.zeros[level];
        const right = cur[2 * i + 1] ?? this.zeros[level];
        next.push(poseidonHash([left, right]));
      }
      layers.push(next);
    }
    this._cachedLayers = layers;
    return layers;
  }

  getRoot(): bigint {
    const layers = this._buildLayers();
    return layers[this.levels][0] ?? this.zeros[this.levels];
  }

  getProof(leafIndex: number): { pathElements: bigint[]; pathIndices: number[] } {
    const layers = this._buildLayers();
    const pathElements: bigint[] = [];
    const pathIndices: number[] = [];
    let idx = leafIndex;
    for (let level = 0; level < this.levels; level++) {
      const sibIdx = idx % 2 === 0 ? idx + 1 : idx - 1;
      pathElements.push(layers[level][sibIdx] ?? this.zeros[level]);
      pathIndices.push(idx % 2);
      idx = Math.floor(idx / 2);
    }
    return { pathElements, pathIndices };
  }
}

import { poseidonHash } from "./crypto";

export const ETH_TOKEN_ADDRESS = 0n;

export interface Entry {
  blinding: bigint;
  amount: bigint;
  tokenAddress: bigint;
  commitment: bigint;
  leafIndex?: number;   // set after on-chain inclusion
}

export type OwnedEntry = Entry & { leafIndex: number };

export function buildEntry(
  spendingPubkey: bigint,
  nullifierKey: bigint,
  blinding: bigint,
  amount: bigint,
  tokenAddress: bigint = ETH_TOKEN_ADDRESS,
): Entry {
  const commitment = poseidonHash([spendingPubkey, nullifierKey, blinding, amount, tokenAddress]);
  return { blinding, amount, tokenAddress, commitment };
}

// Nullifier derivable only after on-chain inclusion (leafIndex known from Transact event).
export function computeNullifier(nullifierKey: bigint, leafIndex: number): bigint {
  return poseidonHash([nullifierKey, BigInt(leafIndex)]);
}

export function randomBlinding(): bigint {
  return BigInt("0x" + require("crypto").randomBytes(31).toString("hex"));
}

import { ethers } from "ethers";
import { MerkleTree } from "./merkle";
import { SMT, aliasHashToSmtKey } from "./smt";
import { buildEntry, computeNullifier, OwnedEntry, ETH_TOKEN_ADDRESS } from "./entry";
import { decodeOutputBlob, decryptOutput, poseidonHash } from "./crypto";

const TRANSACT_ABI = [
  "event Transact(uint256 publicAmount, uint256 tokenAddress, bytes32 indexed inputNullifier0, bytes32 indexed inputNullifier1, bytes32 outputCommitment0, bytes32 outputCommitment1, uint32 outputLeafIndex0, uint32 outputLeafIndex1, bytes encryptedOutput0, bytes encryptedOutput1)",
];
const REGISTRY_ABI = [
  "event AliasRegistered(bytes32 indexed aliasHash, bytes32 spendingPubkey, bytes32 nullifierKey, bytes32 encryptionPubkey)",
  "event KeysUpdated(bytes32 indexed aliasHash, bytes32 spendingPubkey, bytes32 nullifierKey, bytes32 encryptionPubkey)",
  "event AliasDataUpdated(bytes32 indexed aliasHash, bytes32 newDataHash)",
  "event AliasTransferred(bytes32 indexed aliasHash, address indexed previousOwner, address indexed newOwner, bytes32 newSpendingPubkey, bytes32 newNullifierKey, bytes32 newEncryptionPubkey)",
];

const DEFAULT_CHUNK_SIZE = 2_000;
const DELAY_MS = 50;
const delay = (ms: number) => new Promise((res) => setTimeout(res, ms));

export interface Output {
  commitment: bigint;
  leafIndex: number;
  encryptedBlob: string;
  tokenAddress: bigint;
  spentNullifiers: [bigint, bigint];
  blockNumber: number;
  transactionIndex: number;
  logIndex: number;
}

export interface RegistryEntry {
  aliasHash: string;
  spendingPubkey: bigint;
  nullifierKey: bigint;
  encryptionPubkey: Uint8Array;
  dataHash: bigint;
}

export interface ScanResult {
  poolTree: MerkleTree;
  smt: SMT;
  outputs: Output[];
  registryEntries: RegistryEntry[];
  aliasHashByPubkey: Map<bigint, bigint>;
  spentNullifiers: Set<bigint>;
}

export async function scanEvents(
  provider: ethers.Provider,
  contractAddress: string,
  fromBlock: number = 0,
  chunkSize: number = DEFAULT_CHUNK_SIZE,
  onProgress?: (pct: number) => void,
): Promise<ScanResult> {
  const jsIface       = new ethers.Interface(TRANSACT_ABI);
  const regIface      = new ethers.Interface(REGISTRY_ABI);
  const jsTopic       = jsIface.getEvent("Transact")!.topicHash;
  const regTopic      = regIface.getEvent("AliasRegistered")!.topicHash;
  const keysUpdTopic  = regIface.getEvent("KeysUpdated")!.topicHash;
  const dataUpdTopic  = regIface.getEvent("AliasDataUpdated")!.topicHash;
  const transferTopic = regIface.getEvent("AliasTransferred")!.topicHash;

  const latestBlock = await provider.getBlockNumber();

  const allLogs: ethers.Log[] = [];
  let cur = fromBlock;
  const total = latestBlock - fromBlock;
  while (cur <= latestBlock) {
    const end = Math.min(cur + chunkSize - 1, latestBlock);
    if (onProgress) onProgress(Math.floor(((cur - fromBlock) / (total || 1)) * 100));
    const chunk = await provider.getLogs({ address: contractAddress, fromBlock: cur, toBlock: end });
    allLogs.push(...chunk);
    cur = end + 1;
    if (cur <= latestBlock) await delay(DELAY_MS);
  }
  if (onProgress) onProgress(100);

  const outputsByLeafIndex = new Map<number, Output>();
  const spentNullifiers = new Set<bigint>();
  const registryByAlias = new Map<string, RegistryEntry>();
  const aliasHashByPubkey = new Map<bigint, bigint>();

  for (const log of allLogs) {
    const topic = log.topics[0];

    if (topic === jsTopic) {
      const e = jsIface.parseLog({ topics: log.topics as string[], data: log.data })!;
      const tokenAddress = BigInt(e.args[1]);
      const null0 = BigInt(e.args[2]);
      const null1 = BigInt(e.args[3]);
      spentNullifiers.add(null0);
      spentNullifiers.add(null1);

      const comm0 = BigInt(e.args[4]);
      const comm1 = BigInt(e.args[5]);
      const idx0  = Number(e.args[6]);
      const idx1  = Number(e.args[7]);
      const blob0 = e.args[8];
      const blob1 = e.args[9];

      const base = {
        spentNullifiers: [null0, null1] as [bigint, bigint],
        tokenAddress,
        blockNumber: log.blockNumber,
        transactionIndex: log.transactionIndex,
        logIndex: log.index,
      };
      outputsByLeafIndex.set(idx0, { commitment: comm0, leafIndex: idx0, encryptedBlob: blob0, ...base });
      outputsByLeafIndex.set(idx1, { commitment: comm1, leafIndex: idx1, encryptedBlob: blob1, ...base });

    } else if (topic === regTopic) {
      const e = regIface.parseLog({ topics: log.topics as string[], data: log.data })!;
      const aliasHash = e.args[0] as string;
      const spendingPubkey = BigInt(e.args[1]);
      const entry: RegistryEntry = {
        aliasHash,
        spendingPubkey,
        nullifierKey:     BigInt(e.args[2]),
        encryptionPubkey: ethers.getBytes(e.args[3]),
        dataHash:         0n,
      };
      registryByAlias.set(aliasHash, entry);
      aliasHashByPubkey.set(spendingPubkey, BigInt(aliasHash));

    } else if (topic === keysUpdTopic) {
      const e = regIface.parseLog({ topics: log.topics as string[], data: log.data })!;
      const aliasHash = e.args[0] as string;
      const spendingPubkey = BigInt(e.args[1]);
      const existing = registryByAlias.get(aliasHash);
      const entry: RegistryEntry = {
        aliasHash,
        spendingPubkey,
        nullifierKey:     BigInt(e.args[2]),
        encryptionPubkey: ethers.getBytes(e.args[3]),
        dataHash:         existing ? existing.dataHash : 0n,
      };
      registryByAlias.set(aliasHash, entry);
      if (existing) aliasHashByPubkey.delete(existing.spendingPubkey);
      aliasHashByPubkey.set(spendingPubkey, BigInt(aliasHash));

    } else if (topic === dataUpdTopic) {
      const e = regIface.parseLog({ topics: log.topics as string[], data: log.data })!;
      const aliasHash = e.args[0] as string;
      const newDataHash = BigInt(e.args[1]);
      const existing = registryByAlias.get(aliasHash);
      if (existing) {
        existing.dataHash = newDataHash;
        registryByAlias.set(aliasHash, existing);
      }

    } else if (topic === transferTopic) {
      const e = regIface.parseLog({ topics: log.topics as string[], data: log.data })!;
      const aliasHash = e.args[0] as string;
      const newSpendingPubkey = BigInt(e.args[3]);
      const existing = registryByAlias.get(aliasHash);
      const entry: RegistryEntry = {
        aliasHash,
        spendingPubkey: newSpendingPubkey,
        nullifierKey:     BigInt(e.args[4]),
        encryptionPubkey: ethers.getBytes(e.args[5]),
        dataHash:         0n, // Reset on transfer
      };
      registryByAlias.set(aliasHash, entry);
      if (existing) aliasHashByPubkey.delete(existing.spendingPubkey);
      aliasHashByPubkey.set(newSpendingPubkey, BigInt(aliasHash));
    }
  }

  const sortedOutputs = [...outputsByLeafIndex.values()].sort((a, b) => a.leafIndex - b.leafIndex);
  const poolTree = new MerkleTree();
  for (const out of sortedOutputs) {
    poolTree.insert(out.commitment);
  }

  const registryEntries = [...registryByAlias.values()];
  const smt = new SMT();
  for (const entry of registryEntries) {
    const smtKey = aliasHashToSmtKey(BigInt(entry.aliasHash));
    const leaf = poseidonHash([entry.spendingPubkey, entry.nullifierKey, entry.dataHash]);
    smt.update(smtKey, leaf);
  }

  return { poolTree, smt, outputs: sortedOutputs, registryEntries, aliasHashByPubkey, spentNullifiers };
}

export function findMyOutputs(
  outputs: Output[],
  spendingPubkey: bigint,
  nullifierKey: bigint,
  encryptionPrivKey: Uint8Array,
  tokenAddress: bigint = ETH_TOKEN_ADDRESS,
): OwnedEntry[] {
  const found: OwnedEntry[] = [];
  for (const out of outputs) {
    if (out.tokenAddress !== tokenAddress) continue;
    const decoded = decodeOutputBlob(out.encryptedBlob);
    if (!decoded) continue;
    const decrypted = decryptOutput(decoded.encrypted, encryptionPrivKey);
    if (!decrypted) continue;
    if (decrypted.viewTag !== decoded.viewTag) continue;
    const entry = buildEntry(spendingPubkey, nullifierKey, decrypted.blinding, decrypted.amount, tokenAddress);
    if (entry.commitment !== out.commitment) continue;
    found.push({ ...entry, leafIndex: out.leafIndex });
  }
  return found;
}

import { poseidonHash } from "./crypto";

const REGISTRY_LEVELS = 32;

// Lazily computed: zeros[i] = hash of an empty subtree of height i.
// zeros[0] = 0n (sentinel for empty leaf), zeros[i+1] = Poseidon(zeros[i], zeros[i]).
// Must be computed after circomlibjs init().
let ZEROS: bigint[] | null = null;

function getZeros(): bigint[] {
  if (!ZEROS) {
    ZEROS = [0n];
    for (let i = 0; i < REGISTRY_LEVELS; i++) {
      ZEROS.push(poseidonHash([ZEROS[i], ZEROS[i]]));
    }
  }
  return ZEROS;
}

// SMT leaf hash: Poseidon(key, value, 1) — matches circomlib SMTHash1 via PoseidonT4 in Solidity.
function smtHash1(key: bigint, value: bigint): bigint {
  return poseidonHash([key, value, 1n]);
}

// SMT internal node hash: Poseidon(left, right) — matches circomlib SMTHash2 via PoseidonT3.
function smtHash2(left: bigint, right: bigint): bigint {
  return poseidonHash([left, right]);
}

// Sparse Merkle Tree (32 levels) mirroring Halias.sol _smtUpdate/_smtZeros.
// Key = aliasHash % FIELD_PRIME. Value = RegistryLeaf hash.
// Supports in-place updates (key rotation, alias transfer).
export class SMT {
  private nodes = new Map<string, bigint>();
  public root: bigint;

  constructor() {
    this.root = getZeros()[REGISTRY_LEVELS];
  }

  update(key: bigint, value: bigint): void {
    const zeros = getZeros();
    let current = smtHash1(key, value);
    for (let i = 0; i < REGISTRY_LEVELS; i++) {
      const nodePath    = key >> BigInt(i);
      const siblingPath = nodePath ^ 1n;
      const isRight     = (nodePath & 1n) === 1n;
      const sibling     = this.nodes.get(`${i}:${siblingPath}`) ?? zeros[i];
      this.nodes.set(`${i}:${nodePath}`, current);
      current = isRight ? smtHash2(sibling, current) : smtHash2(current, sibling);
    }
    this.root = current;
  }

  getSiblings(key: bigint): bigint[] {
    const zeros = getZeros();
    return Array.from({ length: REGISTRY_LEVELS }, (_, i) => {
      const siblingPath = (key >> BigInt(i)) ^ 1n;
      return this.nodes.get(`${i}:${siblingPath}`) ?? zeros[i];
    });
  }

  serializeNodes(): Record<string, string> {
    const out: Record<string, string> = {};
    for (const [k, v] of this.nodes) {
      out[k] = "0x" + v.toString(16);
    }
    return out;
  }

  static fromSerialized(nodesRaw: Record<string, string>, root: bigint): SMT {
    const smt = new SMT();
    for (const [k, v] of Object.entries(nodesRaw)) {
      smt.nodes.set(k, BigInt(v));
    }
    smt.root = root;
    return smt;
  }
}

const FIELD_PRIME = 21888242871839275222246405745257275088548364400416034343698204186575808495617n;

export function aliasHashToSmtKey(aliasHashBig: bigint): bigint {
  return aliasHashBig % FIELD_PRIME;
}
